import pytest
from boltons.debugutils import wrap_trace

ERR = ValueError('x')

class T:
    def boom(self):
        raise ERR

def test_prop():
    def hook(event, label, obj, attr_name, args, kwargs, result=None):
        return False
    t = wrap_trace(T(), hook=hook, which='boom')
    with pytest.raises(ValueError) as ei:
        t.boom()
    assert ei.value is ERR
